import { PlaneGeometry, BoxGeometry, CircleGeometry, Group, Mesh, Color, PointLight } from 'three/webgpu';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture, positionLocal, normalLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const T = ctx.THREE;
  const root = new Group();
  const owned = [];
  const loadedTextures = [];
  const primitiveResults = [];
  const timelines = [];

  root.userData.handlers = {};

  const ink = new Color('#16161d');
  const paper = new Color('#e8ecf2');
  const accent = new Color('#ff2a38');
  const surface = new Color('#0b0b10');

  const track = (object) => {
    if (object.geometry) owned.push(object.geometry);
    if (object.material) owned.push(object.material);
    return object;
  };

  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3(surface.r, surface.g, surface.b),
    vec3(ink.r, ink.g, ink.b),
    uv().y
  );

  const backdrop = track(new Mesh(new PlaneGeometry(7, 6), backdropMaterial));
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: new Color('#000000'),
    transparent: true,
    opacity: 0.46,
    depthWrite: false
  });

  const contactShadow = track(
    new Mesh(new CircleGeometry(2.35, 64), shadowMaterial)
  );
  contactShadow.scale.set(1.65, 0.32, 1);
  contactShadow.position.set(0, -0.88, -0.92);
  root.add(contactShadow);

  const panelMaterial = new MeshStandardNodeMaterial({
    color: surface,
    roughness: 0.58,
    metalness: 0.48
  });

  const panel = track(new Mesh(new BoxGeometry(5.45, 1.72, 0.16), panelMaterial));
  panel.position.set(0, 0, -0.28);
  root.add(panel);

  const imageMaterial = new MeshStandardNodeMaterial({
    color: paper,
    roughness: 0.62,
    metalness: 0.22
  });

  const imagePlane = track(
    new Mesh(new PlaneGeometry(5.08, 1.34, 64, 64), imageMaterial)
  );
  imagePlane.position.set(0, 0.04, -0.17);
  root.add(imagePlane);

  const dividerMaterial = new MeshBasicNodeMaterial({
    color: paper,
    transparent: true,
    opacity: 0.2
  });

  const divider = track(new Mesh(new PlaneGeometry(4.9, 0.012), dividerMaterial));
  divider.position.set(0, -0.58, -0.05);
  root.add(divider);

  const accentMaterial = new MeshStandardNodeMaterial({
    color: accent,
    emissive: accent,
    emissiveIntensity: 1.25,
    roughness: 0.52,
    metalness: 0.42
  });

  const accentRail = track(new Mesh(new BoxGeometry(0.055, 1.18, 0.11), accentMaterial));
  accentRail.position.set(-2.48, 0, -0.05);
  root.add(accentRail);

  const edgeMaterial = new MeshStandardNodeMaterial({
    color: paper,
    roughness: 0.68,
    metalness: 0.5
  });

  const topEdge = track(new Mesh(new BoxGeometry(4.65, 0.025, 0.08), edgeMaterial));
  topEdge.position.set(0.12, 0.73, -0.06);
  topEdge.scale.x = 0.96;
  root.add(topEdge);

  const rim = new PointLight(accent, 0.78, 5.2, 2);
  rim.position.set(-2.2, 1.3, 1.15);
  root.add(rim);

  const fill = new PointLight(paper, 0.42, 4.5, 2);
  fill.position.set(2.4, -0.8, 0.8);
  root.add(fill);

  const imageUrl = config.imageUrl;
  const depthMapUrl = config.depthMapUrl;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      loadedTextures.push(tex);
      imageMaterial.map = tex;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  if (depthMapUrl) {
    ctx.textureLoader.loadTexture(depthMapUrl).then((depthTex) => {
      loadedTextures.push(depthTex);
      const depthNode = texture(depthTex, uv()).r;
      imageMaterial.positionNode = positionLocal.add(
        normalLocal.mul(depthNode.mul(0.14))
      );
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  root.scale.setScalar(0.985);
  root.position.y = -0.14;

  const entrance = gsap.timeline({ paused: true });
  entrance
    .fromTo(
      root.position,
      { y: -0.54 },
      { y: -0.14, duration: 0.7, ease: 'power3.out' }
    )
    .fromTo(
      root.scale,
      { x: 1.04, y: 1.04, z: 1.04 },
      { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
      '-=0.52'
    );
  entrance.play();
  timelines.push(entrance);

  let hoverTimeline;

  root.userData.handlers.hover = (active = true) => {
    if (hoverTimeline) hoverTimeline.kill();

    hoverTimeline = gsap.timeline();
    hoverTimeline.to(root.position, {
      y: active ? 0.01 : -0.14,
      duration: 0.3,
      ease: 'power2.out'
    });
    hoverTimeline.to(root.rotation, {
      z: active ? -0.018 : 0,
      duration: 0.3,
      ease: 'power2.out'
    }, 0);
    timelines.push(hoverTimeline);
  };

  root.userData.handlers.click = () => {
    const press = gsap.timeline();
    press.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'power2.out'
    });
    press.to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.42,
      ease: 'back.out(2)'
    });
    timelines.push(press);
    ctx.emit('hub-pricing.select', {});
  };

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const apply = ctx.primitives?.[primitive.name];
    if (typeof apply === 'function') {
      const result = apply(root, primitive.params ?? {});
      if (result) primitiveResults.push(result);
    }
  }

  root.userData.cleanup = () => {
    for (const result of primitiveResults) {
      if (typeof result.cleanup === 'function') result.cleanup();
      if (result.timeline && typeof result.timeline.kill === 'function') {
        result.timeline.kill();
      }
    }

    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') timeline.kill();
    }

    root.traverse((object) => {
      if (object.geometry && typeof object.geometry.dispose === 'function') {
        object.geometry.dispose();
      }
      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];
        for (const material of materials) {
          if (material && typeof material.dispose === 'function') {
            material.dispose();
          }
        }
      }
    });

    for (const tex of loadedTextures) {
      if (tex && typeof tex.dispose === 'function') tex.dispose();
    }
  };

  return root;
}
